begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(12);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values ('18700000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp-cancel-tools@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18700000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18700000-0000-0000-0000-000000000002','18700000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18700000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18700000-0000-0000-0000-000000000004','18700000-0000-0000-0000-000000000001','18700000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18700000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18700000-0000-0000-0000-000000000005','18700000-0000-0000-0000-000000000001','18700000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('18700000-0000-0000-0000-000000000006','18700000-0000-0000-0000-000000000002','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('18700000-0000-0000-0000-000000000007','18700000-0000-0000-0000-000000000002','Synthetic staff');
insert into public.shifts(id,organization_id,client_id,start_at,end_at,status) values ('18700000-0000-0000-0000-000000000008','18700000-0000-0000-0000-000000000002','18700000-0000-0000-0000-000000000006','2026-11-01 00:00+00','2026-11-01 01:00+00','published');
insert into private.mcp_shift_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18700000-0000-0000-0000-000000000002',true,'{}','18700000-0000-0000-0000-000000000001',now());
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18700000-0000-0000-0000-000000000002',true,'{}','18700000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18700000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18700000-0000-0000-0000-000000000003","session_id":"18700000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_shift_cancel_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18700000-0000-0000-0000-000000000002',true,'{}','18700000-0000-0000-0000-000000000001',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('cancel187-browser','cancel187-browser','18700000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
select ok(has_function_privilege('mcp_import','public.prepare_mcp_shift_cancel(uuid,uuid,text,text)','execute') and not has_function_privilege('authenticated','public.prepare_mcp_shift_cancel(uuid,uuid,text,text)','execute'),'only MCP can prepare');
select ok(has_function_privilege('mcp_import','public.get_mcp_shift_cancel_result(uuid,uuid)','execute') and not has_function_privilege('authenticated','public.get_mcp_shift_cancel_result(uuid,uuid)','execute'),'only MCP can query result');
select set_config('test.proposal',public.prepare_mcp_shift_cancel('18700000-0000-0000-0000-000000000002','18700000-0000-0000-0000-000000000008','cancel','synthetic')->>'proposal_id',true);
select is(public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'status','confirmation_required','MCP sees confirmation required');
select is((select status from public.shifts where id='18700000-0000-0000-0000-000000000008'),'published','MCP preparation does not mutate shift');
select throws_ok($$select public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000099',current_setting('test.proposal')::uuid)$$,'42501','mcp_shift_read_unavailable','other organization denied');
select is(public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000002','18700000-0000-0000-0000-000000000099'),null::jsonb,'unknown proposal is unavailable');
select set_config('request.jwt.claims','{"sub":"18700000-0000-0000-0000-000000000001","role":"authenticated","session_id":"cancel187-browser"}',true);
select is(public.confirm_mcp_shift_cancel(current_setting('test.proposal')::uuid)->>'status','updated','browser confirms');
select set_config('request.jwt.claims','{"sub":"18700000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18700000-0000-0000-0000-000000000003","session_id":"18700000-0000-0000-0000-000000000005"}',true);
select is(public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'status','updated','MCP sees confirmed result');
select is(public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'google_sync_status','pending_upsert','MCP sees pending sync');
update private.mcp_shift_cancel_controls set enabled=false where organization_id='18700000-0000-0000-0000-000000000002';
select throws_ok($$select public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)$$,'42501','proposal_unavailable','disabled control denies result');
update private.mcp_shift_cancel_controls set enabled=true where organization_id='18700000-0000-0000-0000-000000000002';
update auth.oauth_consents set revoked_at=clock_timestamp() where id='18700000-0000-0000-0000-000000000004';
select throws_ok($$select public.get_mcp_shift_cancel_result('18700000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)$$,'42501','mcp_shift_read_unavailable','revoked OAuth denies result');
select is((select count(*) from public.audit_events where action_type='shift.cancel' and resource_id='18700000-0000-0000-0000-000000000008'),1::bigint,'one audit recorded');
select * from finish();
rollback;
